fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    // We'll use a half-open binary search [low, high)
    let mut low = 0;
    let mut high = arr.len();

    // Invariant: all indices < low have value < target,
    // all indices >= high have value >= target
    while low < high {
        let mid = low + (high - low) / 2;
        if arr[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    // At this point low == high is the first index where arr[index] >= target (if it exists).
    if low < arr.len() && arr[low] == target {
        Some(low)
    } else {
        None
    }
}

